head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.isFirstLoad = false;
// 세션정보를 얻기위한 함수사용
scwin.Secugrp_id = "", scwin.Mkt_id = "", scwin.fr_bz_procs_no = "", scwin.Dd = "", scwin.Isur_cd = "99999", scwin.gubun = "3";
scwin.trsIdx; // insert, update 구분

scwin.getPar, scwin.setPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const fnc = $c.frame.path("../").scwin.getPar; // Provider화면에서 fn_GetPar명칭으로 선언된 함수를 획득
        const arrPar = new Array();
        if (fnc !== undefined) {
            fnc(arrPar); // Provider화면의 callback함수를 호출하여 필요한 인수를 넘겨받는다.
            scwin.Secugrp_id = (arrPar.length >= 1 ? arrPar[0] : ""); // 증권그룹ID
            scwin.Mkt_id = (arrPar.length >= 2 ? arrPar[1] : ""); // 시장구분코드
            scwin.fr_bz_procs_no = (arrPar.length >= 3 ? arrPar[2] : ""); // 업무처리번호(수정시만 유효)
            scwin.Dd = (arrPar.length >= 4 ? arrPar[3] : ""); // 최종거래일 또는 당일자
            scwin.gubun = (arrPar.length >= 5 ? arrPar[3] : ""); // "3";	// 전체 구분값 셋팅 ko_jackal_10.06.15

        }
        await scwin.getRsnCd();

        // alert( "Isur_cd =  " +Isur_cd + "\n"  + " Isur_nm = " + Isur_nm + "\n" + "  Secugrp_id = " + Secugrp_id + "\n" +
        //         "Mkt_id =  " +Mkt_id + "\n" + " fr_bz_procs_no = " + fr_bz_procs_no+ "\n"  ) ;

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제
        buttonSet.setDsclInfo(btn_Dscl, scwin.dscl); // 안내문작성

        buttonSet.setCopyInfo(btn_Search, scwin.getIsuCd, btn_Save); // 조회

        edt_Dd.setValue(scwin.Dd);
        if (scwin.fr_bz_procs_no !== "") {
            // Provider화면 에서 넘겨받은 업무처리번호가 ""가 아니라면 신규작성으로 간주한다.
            edt_Dd.setReadOnly(true);
            await scwin.search();
        } else {
            edt_Dd.setReadOnly(false);
            await scwin.newOnload(); // 신규작성시 호출

        }
        $c.libRoundPanel.PanelToGroupBox(panel_3);
        $c.libRoundPanel.PanelToGroupBox(panel_1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05919.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_OnFail
 * @description On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_OnFail = function() {
    try {
        $c.lc.fn_alertMsg('F');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05919.trs_OnFail" });
    }
};

/**
 * @method
 * @name trs_OnSuccess
 * @description On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        if (buttonSet.status === "D") {
            // 삭제처리의 응답인 경우
            await $c.win.closePopup();
        } else {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05919.trs_OnSuccess" });
    }
};

/**
 * @method
 * @name dts_Mst_OnLoadCompleted
 * @description dts_Mst 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.fr_bz_procs_no === "") {
            dts_Mst.insertRow();
        }

        // 신규처리에 의한 조회인지,  수정에 의한 조회인지를 구별
        if (scwin.fr_bz_procs_no === "") {
            buttonSet.setInsertStatus();
        } else {
            $c.stf.setButtonSetWithDate(edt_DelistDd, false);
        }
        scwin.isFirstLoad = true;
        if (scwin.fr_bz_procs_no === "") {
            cmb_Rsn_Cd.BindColVal = "690019";
            //        cmb_Rsn_Cd.BindColVal = "690019" ;    // 권리행사조건의 달성(조기종료 발생) ko_jackal_10.06.15
            txb_GrndRegulNm.setValue(dts_Rsn.getCellData(cmb_Rsn_Cd.getSelectedIndex() + 1, "REGL"));
        } else {
            cmb_Rsn_Cd.BindColVal = dts_Mst.getCellData(dts_Mst.getRowPosition(), "DELIST_RSN_CD");
        }
        scwin.isFirstLoad = false;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05919.dts_Mst_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05919.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name img_DelistDd_onclick
 * @description img_DelistDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_DelistDd_onclick = function() {
    try {
        popUpCalendar2(edt_DelistDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05919.img_DelistDd_onclick" });
    }
};

/**
 * @method
 * @name cmb_Rsn_Cd_onselchange2
 * @description cmb Rsn Cd onselchange2 처리
 * @returns {void}
 * @hidden N
 */
scwin.cmb_Rsn_Cd_onselchange2 = function() {
    try {
        if (scwin.isFirstLoad) return;
        txb_GrndRegulNm.setValue(dts_Rsn.getCellData(cmb_Rsn_Cd.getSelectedIndex() + 1, "REGL"));
        // alert(dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "CODE") + "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "NAME")+ "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "REGL")) ;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05919.cmb_Rsn_Cd_onselchange2" });
    }
};

/**
 * @method
 * @name cmb_Rsn_Cd_OnSelected
 * @description cmb Rsn Cd On Selected 처리
 * @returns {void}
 * @hidden N
 */
scwin.cmb_Rsn_Cd_OnSelected = function() {

};

/**
 * @method
 * @name btn_Dd_onclick
 * @description btn_Dd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Dd_onclick = function() {
    try {
        if (scwin.fr_bz_procs_no !== "") return;
        popUpCalendar2(edt_Dd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05919.btn_Dd_onclick" });
    }
};

/**
 * @method
 * @name dts_Isu_OnLoadCompleted
 * @description dts_Isu 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {
};

/**
 * @method
 * @name img_SetIsuCd_onclick
 * @description 「종목선택」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SetIsuCd_onclick = function() {
    try {
        scwin.getPar = scwin.getParIsu;
        scwin.setPar = scwin.setParIsu;
        $c.lc.fn_PopFindElwCodeAll();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05919.img_SetIsuCd_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if (scwin.fr_bz_procs_no !== "") {
        url += "&SCREN_ID=" + "ULDSTF05919.xml";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions = {
            id : "sbm_dts_Mst",
            action : "/Delisting.do",
            ref : "",
            target : "dts_Mst=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions2 = {
            id : "sbm_dts_Isu",
            action : "/Delisting.do",
            ref : "",
            target : "dts_Isu=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

/**
 * @method
 * @name newOnload
 * @description new Onload 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.newOnload = async function() {
    url += "&SCREN_ID=" + "ULDSTF05919.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // dts_Mst.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DELLIST_MST_INOUT";
    const sbmOptions = {
        id : "sbm_dts_Mst",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Mst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name getRsnCd
 * @description get Rsn Cd 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getRsnCd = async function() {
    const sbmOptions = {
        id : "sbm_dts_Rsn",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Rsn=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name saveTrs
 * @description 매매거래정지종목은 매번 업무처리 번호를 세팅함
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveTrs = async function() {
    // 매매거래정지종목은 매번 업무처리 번호를 세팅함
    // 종목별 변경이 있을수 있기 때문
    dts_Isu.setBroadcast(false);
    for (let i = 1; i <= dts_Isu.getRowCount(); i++) {
        dts_Isu.setCellData(i, "BZ_PROCS_NO", scwin.fr_bz_procs_no);
    }
    dts_Isu.setBroadcast(true, true);

    // ELW는 항상  종목별기준으로 처리함
    // 1 : 종목별 , 2 : 법인별
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "MKTACT_APPL_OBJ_TP_CD", "1");
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "DELIST_RSN_CD", dts_Rsn.getCellData(cmb_Rsn_Cd.getSelectedIndex() + 1, "CODE"));

    // alert(dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "CODE") + "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "NAME")+ "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "REGL")) ;

    let vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;
    if (scwin.trsIdx === TRS_IDX_INSERT) vScrenProcsTpCD = SCREN_PROCS_TP_CD_02;

    else if (scwin.trsIdx === TRS_IDX_DELETE) vScrenProcsTpCD = SCREN_PROCS_TP_CD_04;
    trs.KeyName = "toinb_dataid4";
    trs.Parameters = "TRS_IDX=" + scwin.trsIdx + ",BZ_PROCS_NO=" + scwin.fr_bz_procs_no + ",COUNT=2" +
        //                                ",LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_307 +
        ",LIST_BZ_TP_CD=" + "313" + // 조기종료에 의한 상장폐지 업무 구분 추가 예정 ko_jackal_10.06.15
        ",DIV_IDX[0]=" + DIV_IDX_DELLIST_MST + ",DIV_IDX[1]=" + DIV_IDX_DELLIST_DTL;
    const sbmOptions = {
        id : "sbm_trs",
        action : "/Delisting.do",
        ref : "dts_Mst,dts_Isu",
        target : "trs=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getIsuCd
 * @description get Isu Cd 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getIsuCd = async function() {
    if (edt_Dd.text.length !== 8) {
        await $c.win.alert("[조기종료일]을 정확히 입력하세요.");
        return false;
    }
    let url = "/Delisting.do?method=searchDelList" +
        //               "&DIV_IDX="+DIV_IDX_DELLIST_DTL  + "&TRS_IDX="+TRS_IDX_NEWSEL  + "&GUBUN_CD=" + edt_Dd.Text ;
        "&DIV_IDX=" + DIV_IDX_DELLIST_LIST_KO_OCCR + "&TRS_IDX=" + TRS_IDX_SELECT + "&GUBUN_CD=" + edt_Dd.getValue(); // 1 index 로 조기종료 데이타 가져오기 ko_jackal_10.06.15

    dts_Isu.DataID = encodeURI(url);
    dts_Isu.reset();
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (dts_Isu.getRowCount() === 0) {
        await $c.win.alert("[상장폐지종목]을 선택하세요.");
        return false;
    }
    if (!$c.lc.checkDdTm("DD", edt_DelistDd, "상장폐지", false)) return false;
    if (!$c.stf.checkEmptyValue(txb_GrndRegulNm, "근거규정")) return false;
    if (!$c.stf.checkMaxLength(txb_GrndRegulNm, 200, "근거규정")) return false;
    if (!$c.stf.checkMaxLength(txa_Remk, 2000, "기타")) return false;
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess('I')) return;
        scwin.fr_bz_procs_no = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
        if (scwin.fr_bz_procs_no.length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            scwin.trsIdx = TRS_IDX_INSERT;
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "BZ_PROCS_NO", scwin.fr_bz_procs_no);
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "ISUR_CD", "99999");
            await scwin.saveTrs();
        }
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    if (await scwin.checkForm()) {
        scwin.trsIdx = TRS_IDX_UPDATE;
        if (!$c.lc.fn_isProcess('U')) return;
        await scwin.saveTrs();
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    await scwin.saveTrs();
};

/**
 * @method
 * @name getParIsu
 * @description ko_jackal_10.06.15
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @param {*} param_dts param_dts
 * @returns {void}
 * @hidden N
 */
scwin.getParIsu = function(arrPar, param_dts) {
    arrPar[0] = scwin.Isur_cd;
    arrPar[1] = scwin.gubun;
    $c.stf.copyDataSet(dts_Isu, param_dts);
};

/**
 * @method
 * @name setParIsu
 * @description ko_jackal_10.06.15
 * @param {*} param_dts param_dts
 * @returns {void}
 * @hidden N
 */
scwin.setParIsu = function(param_dts) {
    // alert(dts_Isu.text);
    $c.stf.copyDataSet(param_dts, dts_Isu);
};

/**
 * @method
 * @name dscl
 * @description 수정한 것이 있으면 체크 됨.(종목제외)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function() {
    // 수정한 것이 있으면 체크 됨.(종목제외)
    if ($c.cp.isModified(dts_Mst) || $c.cp.isModified(dts_Rsn)) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0022", ""));
        return;
    }
    const OldGet = scwin.getPar;
    const OldSet = scwin.setPar;
    scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        arr[0] = "68955D";
        arr[1] = scwin.fr_bz_procs_no;
        arr[2] = "99999";
        arr[3] = '1';
        arr[4] = '';
        arr[5] = '조기종료에 의한 상장폐지';
        $c.stf.copyDataSet(dts_Isu, param_dts_isu);
        $c.stf.copyDataSet(dts_Mst, param_dts_mst);
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "DELIST_RSN_NM", cmb_Rsn_Cd.getText());
        return arr.length;
    };
    scwin.setPar = function(arr) {

    };
    const wth = 740 + 5;
    const hgt = 790 + 30;
    const pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    const options = {
        id: "ULDSTF92024",
        title: "공시안내문작성",
        type: "browserPopup",
        width: wth,
        height: hgt,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/listingcommon/ULDSTF92024.gfm", options);
    scwin.getPar = OldGet;
    scwin.setPar = OldSet;
};

/**
 * @method
 * @name drft
 * @description drft 처리
 * @returns {void}
 * @hidden N
 */
scwin.drft = function() {

};

/**
 * @method
 * @name makt
 * @description makt 처리
 * @returns {void}
 * @hidden N
 */
scwin.makt = function() {

};
